import numpy as np, mw_tool, itertools, json


def goto_mocap(s, target, grip=1., speed=.5, tol=.002, max_steps=120, settle=10):
 for _ in range(max_steps):
  delta=np.asarray(target)-s.data.mocap_pos[0]
  if np.linalg.norm(delta)<tol:break
  s.step(np.r_[np.clip(delta*100,-speed,speed),grip])
 for _ in range(settle):s.step([0,0,0,grip])


def goto_tcp(s,target, grip=1., speed=.5, tol=.003, max_steps=80):
 for _ in range(max_steps):
  delta=np.asarray(target)-s.env.tcp_center
  if np.linalg.norm(delta)<tol:break
  s.step(np.r_[np.clip(delta*20,-speed,speed),grip])


def trial(xoff=-.025, yoff=.04, height=.02, gain=25, grip=1., speed=.2):
 s=mw_tool.Session(); obj=s.obs[4:7].copy();goal=s.target_pos.copy()
 goto_tcp(s,[obj[0]+xoff,obj[1]+yoff,.15],grip=grip)
 goto_tcp(s,[obj[0]+xoff,obj[1]+yoff,height],grip=grip,max_steps=45)
 best=1.; best_actions=None
 for i in range(270):
  obj=s.obs[4:7].copy()
  if s.check()['obj_to_target']<best:
   best=s.check()['obj_to_target'];best_actions=np.array(s.actions)
  target=np.array([obj[0]+xoff, obj[1]+yoff, height])
  if obj[0]>goal[0]-.003:target[0]=obj[0]
  if obj[1]<goal[1]+.003:target[1]=obj[1]+yoff+.012
  s.step(np.r_[np.clip((target-s.env.tcp_center)*gain,-speed,speed),grip])
  if len(s.actions)>480 or np.linalg.norm(obj[:2]-goal[:2])<.004:break
 if best<.07:
  s.replay(best_actions)
  for _ in range(30):s.step([0,0,0,grip])
  if s.check()['obj_to_target']<.04:
   s.save_trajectory(path='/app/output/feedback_best.npz',meta={'xoff':xoff,'yoff':yoff,'height':height,'gain':gain,'speed':speed})
 return s,dict(xoff=xoff,yoff=yoff,height=height,speed=speed,best=best,final=s.check()['obj_to_target'],steps=len(s.actions),obj=s.obs[4:7].tolist())

if __name__=='__main__':
 for xoff,yoff in itertools.product([-.035,-.03,-.025,-.02,-.015,0.],[.025,.035,.045,.055]):
  s,r=trial(xoff,yoff)
  print(json.dumps(r),flush=True)
