import json,itertools
import numpy as np,mw_tool
from orthogonal_exp import trial


def finish(s, retreat=.025, lift=.11, pause=30, speed=.5):
 # Move away from the block before lifting, to avoid adding horizontal force.
 for _ in range(round(retreat/(speed*.01))):s.step([-speed,0,0,1])
 if lift:
  from gen import move
  move(s,[s.env.tcp_center[0],s.env.tcp_center[1],lift],speed=.5,max_steps=50)
 for _ in range(pause):s.step([0,0,0,1])
 return s


def candidate(back_end=.051,side_end=-.048,retreat=.025,pause=30):
 s,r=trial(back_end=back_end,side_end=side_end)
 finish(s,retreat=retreat,pause=pause)
 r.update(back_end=back_end,side_end=side_end,retreat=retreat,pause=pause,distance=s.check()['obj_to_target'],steps=len(s.actions),obj=s.obs[4:7].tolist(),vel=s.data.qvel[-6:-3].tolist())
 return s,r

